import os
import json
import re
from datetime import datetime

def scan_skill(skill_dir):
    report = {
        "scan_time": datetime.now().isoformat(),
        "skill_directory": skill_dir,
        "files_scanned": [],
        "findings": [],
        "suspicious_content": [],
        "risk_level": "low",
        "safe_to_install": True
    }

    # High-risk patterns
    high_risk_patterns = [
        (r'base64.*-d|base64 --decode', 'Base64 decode command'),
        (r'xattr\s+-d\s+quarantine', 'macOS Gatekeeper bypass'),
        (r'curl\s+.*\|\s*(ba)?sh', 'Pipe to shell execution'),
        (r'wget\s+.*\|\s*(ba)?sh', 'Pipe to shell execution'),
        (r'passwords?\.(txt|csv|log)', 'Password archive'),
        (r'secrets?\.(txt|csv|log)', 'Secrets file'),
        (r'eval\s+\$', 'Dynamic eval with variable'),
    ]

    # Medium-risk patterns
    medium_risk_patterns = [
        (r'chmod\s+\+x', 'Making file executable'),
        (r'\.(hidden|\.\w+)', 'Hidden file reference'),
        (r'cron|launchd|systemd', 'Persistence mechanism'),
        (r'\$\{?HOME\}?.*/\.\w+', 'Hidden file in HOME'),
    ]

    # Check for hidden files
    hidden_files = []
    for root, dirs, files in os.walk(skill_dir):
        for d in dirs:
            if d.startswith('.'):
                hidden_files.append(os.path.join(root, d))
        for f in files:
            if f.startswith('.'):
                hidden_files.append(os.path.join(root, f))

    # Scan all files
    for root, dirs, files in os.walk(skill_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            report["files_scanned"].append(filepath)

            try:
                with open(filepath, 'r', errors='ignore') as f:
                    content = f.read()

                # Check high-risk patterns
                for pattern, desc in high_risk_patterns:
                    if re.search(pattern, content, re.IGNORECASE):
                        report["suspicious_content"].append({
                            "file": filepath,
                            "pattern": pattern,
                            "description": desc,
                            "risk": "high"
                        })
                        report["risk_level"] = "high"
                        report["safe_to_install"] = False

                # Check medium-risk patterns
                for pattern, desc in medium_risk_patterns:
                    if re.search(pattern, content, re.IGNORECASE):
                        report["suspicious_content"].append({
                            "file": filepath,
                            "pattern": pattern,
                            "description": desc,
                            "risk": "medium"
                        })
                        if report["risk_level"] != "high":
                            report["risk_level"] = "medium"

                # Check for prompt injection indicators
                injection_indicators = ['ignore previous instructions', 'system prompt', 
                                       'you are now', 'new directive', 'override']
                for indicator in injection_indicators:
                    if indicator in content.lower():
                        report["suspicious_content"].append({
                            "file": filepath,
                            "pattern": indicator,
                            "description": "Possible prompt injection",
                            "risk": "high"
                        })
                        report["risk_level"] = "high"
                        report["safe_to_install"] = False

            except Exception as e:
                report["findings"].append(f"Could not read {filepath}: {str(e)}")

    # Report hidden files
    if hidden_files:
        report["suspicious_content"].append({
            "type": "hidden_files",
            "files": hidden_files,
            "description": "Hidden files detected",
            "risk": "medium"
        })
        if report["risk_level"] == "low":
            report["risk_level"] = "medium"

    # Summary
    report["findings"].append(f"Scanned {len(report['files_scanned'])} files")
    report["findings"].append(f"Found {len(report['suspicious_content'])} suspicious items")

    return report

if __name__ == "__main__":
    report = scan_skill("sample_skill")
    with open("scan_report.json", "w") as f:
        json.dump(report, f, indent=2)
    print("Scan complete. Results saved to scan_report.json")
    print(json.dumps(report, indent=2))
